mapper.select:
SELECT allocation_hash
FROM refund_authorization
WHERE source_no=#{sourceNo}

mapper.update:
UPDATE refund_authorization
SET allocation_hash=#{allocationHash}
WHERE source_no=#{sourceNo} AND allocation_hash IS NULL

UPDATE order_item_unit
SET reserved_refund_cents=#{reservedRefundCents},active_aftersale_no=#{sourceNo},return_state=#{returnState},version=version+1
WHERE id=#{id} AND active_aftersale_no IS NULL AND reserved_refund_cents=0 AND return_state='NONE' AND paid_amount_cents-succeeded_refund_cents>=#{reservedRefundCents}

UPDATE return_stock_task
SET state='RUNNING',claim_version=claim_version+1,attempt_count=attempt_count+1,lease_until=UTC_TIMESTAMP(3)+INTERVAL 30 SECOND
WHERE source_no=#{sourceNo}

UPDATE return_stock_task
SET state=#{state},last_error=#{lastError},lease_until=NULL,next_retry_at=UTC_TIMESTAMP(3)+INTERVAL 5 SECOND
WHERE source_no=#{sourceNo} AND state='RUNNING' AND claim_version=#{claimVersion}

UPDATE order_return_receipt
SET status='APPLIED'
WHERE source_no=#{sourceNo}
